	"sap/sf/attendancerecording/timesheet/fragment/timeSheetSummary/TimeContainersTable.fragment.xml":'\n<core:FragmentDefinition controllerName="sap.sf.attendancerecording.timesheet.controller.TimeSheetSummary"\n                         xmlns="sap.m"\n                         xmlns:core="sap.ui.core"><VBox><Table id="timeContainersTable" noDataText="{i18n>ATTENDANCE_RECORDING_TextNoDataTimeContainersTable}"\n                items="{timeContainers}"\n                ariaLabelledBy="timeContainersTableSummaryLabel"><customData><core:CustomData key="help-id" value="tlm-ts-timeContainersTable" writeToDom="true" /></customData><columns><Column><Text id="timeContainerNameHeader" text="{i18n>ATTENDANCE_RECORDING_LabelNameOfTimeContainer}"\n                          wrapping="true"\n                          wrappingType="Hyphenated"/></Column><Column hAlign="End"><Text id="timePeriodColumnHeader" text="{i18n>ATTENDANCE_RECORDING_LabelTimePeriod}"\n                          wrapping="true"\n                          wrappingType="Hyphenated"/></Column><Column hAlign="End" demandPopin="true" minScreenWidth="Tablet" popinDisplay="Inline"><Text id="timeContainerValueColumnHeader" text="{i18n>ATTENDANCE_RECORDING_LabelValueOfTimeContainer}"\n                          wrapping="true"\n                          wrappingType="Hyphenated"/></Column></columns><items><ColumnListItem><cells><Text text="{timeTypeGroupName}"/><Text text="{ parts: [\'startDate\', \'endDate\'], formatter: \'.formatter.toDateIntervalShort\', useRawValues:true }"/><Text text="{ parts: [\'value\', \'timeCategory\'], formatter: \'.formatter.toFormattedValue\', useRawValues:true}"/></cells></ColumnListItem></items></Table><core:InvisibleText id="timeContainersTableSummaryLabel" text="{i18n>ATTENDANCE_RECORDING_TextTimeContainerTableSummary}" /></VBox></core:FragmentDefinition>\n',
	"sap/sf/attendancerecording/timesheet/fragment/timeSheetSummary/TimeRecordingAppointmentDetailsPopover.fragment.xml":'\n<core:FragmentDefinition controllerName="sap.sf.attendancerecording.timesheet.controller.TimeSheetSummary"\n                         xmlns="sap.m"\n                         xmlns:core="sap.ui.core"\n                         xmlns:form="sap.ui.layout.form"><ResponsivePopover id="timeRecordingAppointmentDetailsPopover"\n                       title="{singlePlanningCalendar>title}"\n                       placement="VerticalPreferredBottom"\n                       beforeClose="onAppointmentDetailsPopoverBeforeClose"\n                       afterClose="onAppointmentDetailsPopoverAfterClose"><customData><core:CustomData key="help-id" value="tlm-ts-timeRecordingAppointmentDetailsPopover" writeToDom="true" /></customData><beginButton><Button id="closePopoverButton" text="{i18n>COMMON_Close}" press="onAppointmentPopoverCloseButtonPress"><customData><core:CustomData key="help-id" value="tlm-ts-timeRecordingAppointmentDetailsPopoverClosePopoverButton" writeToDom="true" /></customData></Button></beginButton><form:SimpleForm editable="false" width="19rem" layout="ColumnLayout" ariaLabelledBy="appointmentDetailsLabel" labelSpanXL="12" labelSpanL="12" labelSpanM="12"><form:content><Label id="dateLabel" text="{i18n>ATTENDANCE_RECORDING_APPOINTMENT_DATE}" /><Text id="date" text="{path: \'singlePlanningCalendar>startDate\', type: \'sap.ui.model.odata.type.String\', formatter: \'.formatter.toLocalDate\'}" /><Label id="statusLabel" text="{i18n>ATTENDANCE_RECORDING_LabelStatus}"/><ObjectStatus id="statusObjectStatus" text="{singlePlanningCalendar>approvalStatusText}" state="{parts: [\n\t\t\t\t\'singlePlanningCalendar>approvalStatusKey\',\n\t\t\t\t\'approvalStatus>/\',\n\t\t\t\t\'singlePlanningCalendar>isAbsence\'\n\t\t\t], formatter: \'.formatter.toApprovalState\'}"\n                          stateAnnouncementText=""><customData><core:CustomData key="help-id" value="tlm-ts-timeRecordingAppointmentDetailsPopoverStatusObjectStatus" writeToDom="true" /></customData></ObjectStatus><Label id="timeTypeLabel" text="{i18n>ATTENDANCE_RECORDING_LabelRecordType}"/><Text id="timeTypeText" text="{singlePlanningCalendar>timeTypeName}" class="sapMTextBreakWord"/><Label id="timeTypeCategoryLabel" text="{i18n>ATTENDANCE_RECORDING_LABEL_TIME_TYPE_CATEGORY}"/><Text id="timeTypeCategoryText" text="{singlePlanningCalendar>timeTypeCategoryName}"/><Label id="durationLabel" text="{i18n>ATTENDANCE_RECORDING_LabelTimeRecordDurationValue}"/><Text id="durationText" text="{singlePlanningCalendar>duration}"/></form:content></form:SimpleForm><core:InvisibleText id="appointmentDetailsLabel" text="{i18n>ATTENDANCE_RECORDING_APPOINTMENT_DETAILS_ARIA_LABEL}" /></ResponsivePopover></core:FragmentDefinition>\n',
