	"sap/sf/attendancerecording/timesheet/fragment/timeSheetSummary/TimeRecordingsSummary.fragment.xml":'\n<core:FragmentDefinition controllerName="sap.sf.attendancerecording.timesheet.controller.TimeSheetSummary"\n                         xmlns="sap.ui.layout.form"\n                         xmlns:m="sap.m"\n                         xmlns:core="sap.ui.core"\n                         xmlns:sfCommons="sap.sf.commons"><Form id="timeRecordingsSummaryForm" width="100%" class="verticalAlignmentColumnsXL"><layout><ColumnLayout\n                columnsM="2"\n                columnsL="3"\n                columnsXL="3"/></layout><formContainers><FormContainer id="valuationResultContainer" formElements="{valuationResults}"><customData><core:CustomData key="help-id" value="tlm-ts-valuationResultContainer" writeToDom="true" /></customData><title><core:Title id="valuationResultContainerTitle"\n                      text="{i18n>ATTENDANCE_RECORDING_LabelValuationResults}"\n                      tooltip="{i18n>ATTENDANCE_RECORDING_LabelValuationResults}" level="H3"/></title><FormElement label="{timeTypeGroupName}"><fields><sfCommons:PreviousValue currentValue="{ parts: [\'value\', \'timeCategory\'], formatter:\'.formatter.toFormattedValuePreviousValue\', useRawValues:true}" previousValue="{ parts: [\'previousValue\', \'timeCategory\'], formatter:\'.formatter.toFormattedValuePreviousValue\', useRawValues:true}"/></fields></FormElement></FormContainer><FormContainer id="onCallContainer"><customData><core:CustomData key="help-id" value="tlm-ts-onCallContainer" writeToDom="true" /></customData><title><core:Title id="onCallContainerTitle"\n                      text="{i18n>ATTENDANCE_RECORDING_LabelOnCall}"\n                      tooltip="{i18n>ATTENDANCE_RECORDING_LabelOnCall}" level="H3"/></title></FormContainer><FormContainer id="allowanceContainer"><customData><core:CustomData key="help-id" value="tlm-ts-allowanceContainer" writeToDom="true" /></customData><title><core:Title id="allowanceContainerTitle"\n                      text="{i18n>ATTENDANCE_RECORDING_LabelAllowance}"\n                      tooltip="{i18n>ATTENDANCE_RECORDING_LabelAllowance}" level="H3"/></title></FormContainer><FormContainer id="absenceContainer"><customData><core:CustomData key="help-id" value="tlm-ts-absenceContainer" writeToDom="true" /></customData><title><core:Title id="absenceContainerTitle"\n                      text="{i18n>ATTENDANCE_RECORDING_LabelAbsence}"\n                      tooltip="{i18n>ATTENDANCE_RECORDING_LabelAbsence}" level="H3"/></title></FormContainer></formContainers></Form></core:FragmentDefinition>',
